19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number | undefined> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
32	
33	const COMPONENT_BLOCK_SIZE = 3;
34	const COMPONENT_BLOCK_PREMIUM = 60;
35	
36	const policyBasePremiumOf = (step: QuoteStep): number => {
37	  if (step.items.length === COMPONENT_BLOCK_SIZE && step.items.every((item) => item.type === "rune")) {
38	    return COMPONENT_BLOCK_PREMIUM;
39	  }
40	  return step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
41	};
42	
43	/** Kept as an exact fraction — only the final premium is rounded. */
44	const premiumBeforeRounding = (step: QuoteStep): number => {
45	  const policyBasePremium = policyBasePremiumOf(step);
46	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
47	  return policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE;
48	};
49	
50	/** Rounded up, in the MHPCO's favour. */
51	const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));
52	
53	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
54	  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
55	});
