const COMPONENT_TYPES = new Set(["rune"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

/** A "building block": exactly 3 components, all of the same type. */
const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => isComponent(item) && item.type === items[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const policyBasePremiumOf = (step: QuoteStep): number =>
  formsComponentBlock(step.items) ? COMPONENT_BLOCK_PREMIUM : sumOfItemBasePremiums(step.items);
